//d3vlg4qjb80h8n.cloudfront.net/file_library/videos/migration/brightcove/6365284377112/6365284377112.m3u8\", \"drm\": false}, {\"title\": \"(All Notes) Class-54 | Computer Security\", \"type\": \"video\", \"url\": \"https://d3vlg4qjb80h8n.cloudfront.net/file_library/videos/migration/brightcove/6365317715112/6365317715112.m3u8\", \"drm\": false}]}, {\"name\": \"His & Gen of Computer (3)\", \"items\": [{\"title\": \"(All Notes) Class-55 | His & Gen of Computer\", \"type\": \"video\", \"url\": \"https://d3vlg4qjb80h8n.cloudfront.net/file_library/videos/channel_vod_non_drm_hls/4478768/175214059762281268445/175214059762281268445_1268445.m3u8\", \"drm\": false}, {\"title\": \"(All Notes) Class-56 | His & Gen of Computer\", \"type\": \"video\", \"url\": \"https://d3vlg4qjb80h8n.cloudfront.net/file_library/videos/channel_vod_non_drm_hls/4479790/175222648040763199068/175222648040763199068_3199068.m3u8\", \"drm\": false}, {\"title\": \"(All Notes) Class-57 | His & Gen of Computer\", \"type\": \"video\", \"url\": \"https://d14v4v80cpjht7.cloudfront.net/file_library/videos/channel_vod_non_drm_hls/4481547/175248552716694800893/175248552716694800893_4800893.m3u8\", \"drm\": false}]}];\n  const gridEl = document.getElementById('classesGrid');\n  const searchInputEl = document.getElementById('classesSearchInput');\n  const clearBtnEl = document.getElementById('classesClearBtn');\n  const expandAllBtnEl = document.getElementById('classesExpandAllBtn');\n  const collapseAllBtnEl = document.getElementById('classesCollapseAllBtn');\n  const breadcrumbEl = document.getElementById('classesBreadcrumb');\n\n  const folders = rawData.map(function(folder, folderIndex){\n    const items = folder.items.map(function(item, itemIndex){\n      return {\n        id: folderIndex + '-' + itemIndex,\n        title: item.title,\n        lower: item.title.toLowerCase(),\n        type: item.type,\n        url: item.url,\n        drm: !!item.drm\n      };\n    });\n    return {\n      index: folderIndex, 